namespace {

    // the soft white disc of the "particle" texture default (upstream's
    // particles::makeParticleTexture, whose particles/ParticleSimulation S20 replaces): RGBA
    // bytes in memory (little endian), the alpha falling off as (1 - r^2)^2
    void makeSoftDiscTexture(uint32_t* pixels, int size){
        for (int y = 0; y < size; y++){
            for (int x = 0; x < size; x++){
                const float u = ((float)x + 0.5f) / (float)size * 2.0f - 1.0f;
                const float v = ((float)y + 0.5f) / (float)size * 2.0f - 1.0f;
                const float r2 = std::min(1.0f, u * u + v * v);
                const float a = (1.0f - r2) * (1.0f - r2);
                const uint32_t alpha = (uint32_t)std::lround(std::min(1.0f, std::max(0.0f, a)) * 255.0f);
                pixels[y * size + x] = 0x00FFFFFFu | (alpha << 24);
            }
        }
    }

}

namespace {

    // The nearest variant that is ready while `properties` is still being built or created
    // (spec S32 R8): the first of ShaderPool::getFallbackProperties (layout-compatible by
    // construction) that is ready, with `customId` and then, for a built-in Lit reference, with
    // the built-in id. None is requested: only what is already there stands in. Null: none ready.
    std::shared_ptr<ShaderRender> readyStandIn(ShaderType type, uint64_t properties, uint16_t& customId, bool builtinToo){
        for (uint64_t candidate : ShaderPool::getFallbackProperties(type, properties)){
            if (ShaderPool::isShaderReady(type, candidate, customId))
                return ShaderPool::get(type, candidate, customId);
            if (builtinToo && customId != 0 && ShaderPool::isShaderReady(type, candidate, 0)){
                customId = 0;
                return ShaderPool::get(type, candidate, 0);
            }
        }
        return nullptr;
    }

}

namespace {
    constexpr int SPOT_MASK_TILE_SIZE = 256;

    static_assert(sizeof(Matrix4) == sizeof(float) * 16);
    // the "shader part" of Material is floats: u_fs_pbrParams is a prefix of it
    static_assert(sizeof(Vector4) == sizeof(float) * 4 && sizeof(Vector3) == sizeof(float) * 3);

    // The bytes of Material's shader part a Lit variant's u_fs_pbrParams declares (mesh.frag):
    // lit 12 floats, unlit with the alpha mask 8, unlit 4; a Stochastic Tiling ('Sto') variant
    // all 16, its stochastic vec4 last (an unlit one pads up to it), or what a fork made before
    // declares (reflectedSize)
    unsigned int getLitParamsSize(uint64_t properties, unsigned int reflectedSize){
        if ((properties & shaderPropertyBit(5)) && reflectedSize > 0)
            return std::min((unsigned int)(sizeof(float) * 16), reflectedSize);
        if (!(properties & shaderPropertyBit(0)))
            return sizeof(float) * 12;
        if (properties & shaderPropertyBit(24))
            return sizeof(float) * 8;
        return sizeof(float) * 4;
    }

    bool bindSkinningResource(ObjectRender& render, ShaderData& shader, MeshComponent& mesh){
        JE_GPU_ALLOC_SCOPE(Meshes, "Skinning");
        // the palette is the skin's (MeshSystem sizes it at the model load); a skinned mesh whose
        // model has not given it one yet draws with one identity row, never past its resource
        if (mesh.bonesMatrix.stored() == 0)
            mesh.bonesMatrix.resize(1);
        const uint32_t rows = static_cast<uint32_t>(mesh.bonesMatrix.stored());
        // a resource of another palette (the model reloaded with another skin) is made again
        if (mesh.bonesUploadRows != rows){
            if (mesh.bonesBuffer.isCreated())
                mesh.bonesBuffer.destroyBuffer();
            if (mesh.bonesTexture.isCreated())
                mesh.bonesTexture.destroyTexture();
            mesh.bonesUploadRows = 0;
        }
        const unsigned int size = static_cast<unsigned int>(rows * sizeof(Matrix4));
        const int storageSlot = shader.getStorageBufferIndex(StorageBufferType::VS_SKINNING);
        if (storageSlot != -1){
            if (!mesh.bonesBuffer.isCreated() &&
                    !mesh.bonesBuffer.createBuffer(size, nullptr, BufferType::STORAGE_BUFFER, BufferUsage::STREAM))
                return false;
            render.addStorageBuffer(storageSlot, ShaderStageType::VERTEX, &mesh.bonesBuffer);
        }else{
            const auto textureSlot = shader.getTextureIndex(TextureShaderType::BONES);
            if (textureSlot.first == -1)
                return false;
            // a row per joint: a skin taller than the device's textures cannot load on this path
            const int maxRows = SystemRender::getFeatures().maxTextureSize2D;
            if (maxRows > 0 && rows > static_cast<uint32_t>(maxRows)){
                Log::error("Cannot load a skin of %u joints: its bone palette is a texture of %u rows, and this device's textures hold at most %d",
                           rows, rows, maxRows);
                return false;
            }
            if (!mesh.bonesTexture.isCreated() &&
                    !mesh.bonesTexture.createDynamicTexture("mesh-bones", 4, static_cast<int>(rows))){
                Log::error("Cannot make the bone palette of a skin of %u joints (a texture of 4 x %u)", rows, rows);
                return false;
            }
            render.addTexture(textureSlot, ShaderStageType::VERTEX, &mesh.bonesTexture);
        }
        mesh.bonesUploadRows = rows;
        mesh.needUpdateBones = true;
        return true;
    }

    // u_vs_lattice and the record texture of one submesh's draw (includes/lattice.glsl), for a
    // render loaded with a lattice variant (slot -1: none, or a fork without the include).
    // False when the record texture could not be made: the draw would miss a binding
    bool applyLattice(ObjectRender& render, int slot, std::pair<int, int> textureSlot, MeshComponent& mesh,
                      unsigned int submesh, bool stretch){
        if (slot == -1 && textureSlot.first == -1)
            return true;
        if (textureSlot.first != -1){
            if (!mesh.lattice.texture.isCreated())
                return false;
            render.addTexture(textureSlot, ShaderStageType::VERTEX, &mesh.lattice.texture);
        }
        if (slot != -1){
            Vector4 block[2];
            LatticeRender::getUniformBlock(mesh.lattice, submesh, stretch, block);
            render.applyUniformBlock(slot, sizeof(block), block);
        }
        return true;
    }

    static_assert(VAT_BLOCK_CLIPS == vat::VAT_MAX_CLIPS, "u_vs_vat's clip table is vat::VAT_MAX_CLIPS long");

    // u_vs_vat and the payload of one submesh's draw (includes/vat.glsl), for a render loaded
    // with a Vertex Animation variant (slot -1: none, or a fork without the include). False when
    // the payload is missing: the draw would read no texture
    bool applyVat(ObjectRender& render, int slot, std::pair<int, int> textureSlot, MeshComponent& mesh,
                  const Submesh& submesh){
        if (slot == -1 && textureSlot.first == -1)
            return true;
        VatMeshState& state = mesh.vat;
        if (!state.texture || state.block.size() != size_t(VAT_BLOCK_HEADER + VAT_BLOCK_CLIPS))
            return false;
        if (textureSlot.first != -1){
            render.addTexture(textureSlot, ShaderStageType::VERTEX, state.texture);
        }
        if (slot != -1){
            // the bone index and weight scales of this submesh's JOINTS_0 / WEIGHTS_0 (as
            // applySkinningUniform's normAdjust)
            state.block[0].y = submesh.hasSkinningNormalization ? submesh.normAdjustJoint : mesh.normAdjustJoint;
            state.block[0].z = submesh.hasSkinningNormalization ? submesh.normAdjustWeight : mesh.normAdjustWeight;
            render.applyUniformBlock(slot, (unsigned int)(state.block.size() * sizeof(Vector4)), state.block.data());
        }
        return true;
    }

    // i_vat0 / i_vat1 of an instanced mesh loaded with a Vertex Animation variant (a render whose
    // shader does not read them leaves them out)
    void addVatInstanceAttributes(ObjectRender& render, ShaderData& shaderData, InstancedMeshComponent& instmesh){
        if (!instmesh.vatBuffer.getRender()->isCreated())
            return;
        for (auto const &attr : instmesh.vatBuffer.getAttributes()) {
            render.addAttribute(shaderData.getAttrIndex(attr.first), instmesh.vatBuffer.getRender(), attr.second.getElements(), attr.second.getDataType(), instmesh.vatBuffer.getStride(), attr.second.getOffset(), attr.second.getNormalized(), attr.second.getPerInstance());
        }
    }

    // a clip's flags in u_vs_vat (includes/vat.glsl): wrap 0 loop, 1 once or clamp forever,
    // 2 ping-pong; + 4 interpolate; + 8 rest none
    float vatClipFlags(const vat::VatClip& clip){
        int wrap = 1;
        if (clip.wrap == ClipWrapMode::Loop)
            wrap = 0;
        else if (clip.wrap == ClipWrapMode::PingPong)
            wrap = 2;
        return float(wrap + (clip.interpolate ? 4 : 0) + (clip.restNone ? 8 : 0));
    }

    // whether every submesh has the attributes a Vertex Animation variant reads: _VAT_INDEX
    // (Vertices) or JOINTS_0 and WEIGHTS_0 (Bones)
    bool meshHasVatAttributes(const MeshComponent& mesh, VatVariant variant){
        if (mesh.numSubmeshes == 0)
            return false;
        auto has = [&mesh](const Submesh& submesh, AttributeType type){
            if (submesh.attributes.count(type))
                return true;
            const Buffer* buffers[] = {&mesh.buffer};
            for (const Buffer* buffer : buffers){
                if (buffer->isRenderAttributes() && buffer->getAttributes().count(type))
                    return true;
            }
            for (unsigned int b = 0; b < mesh.numExternalBuffers; b++){
                if (mesh.eBuffers[b].isRenderAttributes() && mesh.eBuffers[b].getAttributes().count(type))
                    return true;
            }
            return false;
        };
        for (unsigned int s = 0; s < mesh.numSubmeshes; s++){
            const Submesh& submesh = mesh.submeshes[s];
            if (variant == VatVariant::BONES){
                if (!has(submesh, AttributeType::BONEIDS) || !has(submesh, AttributeType::BONEWEIGHTS))
                    return false;
            }else if (!has(submesh, AttributeType::VAT_INDEX)){
                return false;
            }
        }
        return true;
    }

    void applySkinningUniform(ObjectRender& render, int slot, const MeshComponent& mesh,
                              const Submesh& submesh){
        Vector4 normAdjust(
            submesh.hasSkinningNormalization ? submesh.normAdjustJoint : mesh.normAdjustJoint,
            submesh.hasSkinningNormalization ? submesh.normAdjustWeight : mesh.normAdjustWeight,
            0.0f, 0.0f);
        render.applyUniformBlock(slot, sizeof(normAdjust), &normAdjust);
    }

    // (instanceFadeCullEnd: RenderSystemShared.h)

    // the mesh model matrix without its translation, inverted: what brings a world rotation
    // and scale back into the mesh's space (a particle instance is built in the world)
    Matrix4 inverseLinear(const Matrix4& model){
        Matrix4 linear = model;
        linear.set(3, 0, 0.0f);
        linear.set(3, 1, 0.0f);
        linear.set(3, 2, 0.0f);
        const Matrix4 inverse = linear.inverse();
        return inverse.isValid() ? inverse : Matrix4();
    }

    // A version 2 Particle System's instance (InstanceParticleRender, particles spec 6.4) in
    // its mesh's space: the instance's position is there already; its rotation and its scale
    // (the particle's world size) are made in the world for the alignment and the camera,
    // limited to the min/max share of the viewport height, moved by the pivot (in particle
    // sizes), then brought back by `inverseLinear` (the mesh's own rotation and scale undone)
    Matrix4 particleInstanceMatrix(const InstanceData& instance, const InstanceParticleRender& render, const Transform& transform,
                                   const Matrix4& inverseLinearModel, const Quaternion& cameraRotation, const Vector3& cameraPosition,
                                   const CameraComponent& camera){
        const Vector3 worldPosition = transform.modelMatrix * instance.position;
        Vector3 scale = instance.scale;
        Quaternion rotation;
        // the min/max share of the viewport (Billboard particles only: the sync writes them for
        // that mode), before a stretch lengthens the quad
        if (render.minSize > 0.0f || render.maxSize > 0.0f){
            const float extent = std::max(std::fabs(scale.x), std::fabs(scale.y));
            float viewport;
            if (camera.type == CameraType::CAMERA_PERSPECTIVE){
                const Vector3 forward = cameraRotation * Vector3(0.0f, 0.0f, -1.0f);
                const float depth = std::max(1e-4f, (worldPosition - cameraPosition).dotProduct(forward));
                viewport = depth * 2.0f * std::tan(camera.yfov * 0.5f);
            }else{
                viewport = std::fabs(camera.topClip - camera.bottomClip);
            }
            if (viewport > 0.0f && extent > 0.0f){
                const float fraction = extent / viewport;
                float limited = fraction;
                if (render.maxSize > 0.0f) limited = std::min(limited, render.maxSize);
                if (render.minSize > 0.0f) limited = std::max(limited, render.minSize);
                scale = scale * (limited / fraction);
            }
        }

        const Vector3 cameraUp = cameraRotation * Vector3(0.0f, 1.0f, 0.0f);
        auto roll = [&](float angle){
            Quaternion q;
            q.fromAngleAxis(Angle::radToDefault(angle), Vector3(0.0f, 0.0f, 1.0f));
            return q;
        };
        switch (render.alignment){
            case InstanceAlignment::None:
            case InstanceAlignment::View:
                rotation = cameraRotation * instance.rotation;
                break;
            case InstanceAlignment::World:
                rotation = instance.rotation;
                break;
            case InstanceAlignment::Local:
                rotation = transform.worldRotation * instance.rotation;
                break;
            case InstanceAlignment::Facing: {
                const Vector3 toCamera = cameraPosition - worldPosition;
                rotation = (toCamera.squaredLength() > 1e-12f ? Quaternion::lookRotation(toCamera, cameraUp) : cameraRotation) * instance.rotation;
                break;
            }
            case InstanceAlignment::Velocity: {
                const Vector3& v = instance.velocity;
                rotation = (v.squaredLength() > 1e-12f ? Quaternion::lookRotation(v, Vector3(0.0f, 1.0f, 0.0f)) : Quaternion()) * instance.rotation;
                break;
            }
            case InstanceAlignment::Vertical: {
                // upright, turned about the world's Y to the camera
                Vector3 toCamera = cameraPosition - worldPosition;
                toCamera.y = 0.0f;
                if (toCamera.squaredLength() < 1e-12f){
                    toCamera = cameraRotation * Vector3(0.0f, 0.0f, 1.0f);
                    toCamera.y = 0.0f;
                }
                rotation = (toCamera.squaredLength() > 1e-12f ? Quaternion::lookRotation(toCamera, Vector3(0.0f, 1.0f, 0.0f)) : Quaternion()) * roll(instance.roll);
                break;
            }
            case InstanceAlignment::Horizontal: {
                // flat, facing up, turned about the world's Y by the roll
                Quaternion flat;
                flat.fromAngleAxis(Angle::radToDefault(-1.57079632679f), Vector3(1.0f, 0.0f, 0.0f));
                Quaternion turn;
                turn.fromAngleAxis(Angle::radToDefault(instance.roll), Vector3(0.0f, 1.0f, 0.0f));
                rotation = turn * flat;
                break;
            }
            case InstanceAlignment::Stretched: {
                const Vector3& v = instance.velocity;
                const float speed = v.length();
                Vector3 toCamera = cameraPosition - worldPosition;
                if (speed > 1e-5f && toCamera.squaredLength() > 1e-12f){
                    // X along the velocity, the face turned to the camera about it
                    const Vector3 axisX = v / speed;
                    toCamera.normalize();
                    Vector3 normal = toCamera - axisX * toCamera.dotProduct(axisX);
                    if (normal.squaredLength() < 1e-10f){
                        // moving along the view ray: any axis across the velocity (the camera's
                        // up, or its right when the velocity is vertical on screen)
                        Vector3 across = cameraUp;
                        if (std::fabs(across.dotProduct(axisX)) > 0.99f) across = cameraRotation * Vector3(1.0f, 0.0f, 0.0f);
                        normal = across - axisX * across.dotProduct(axisX);
                    }
                    normal.normalize();
                    const Vector3 axisY = normal.crossProduct(axisX);
                    rotation = Quaternion(axisX, axisY, normal);
                    const float length = std::fabs(scale.x) * render.lengthScale + speed * render.velocityScale;
                    scale.x = std::copysign(length, scale.x);
                }else{
                    rotation = cameraRotation * roll(instance.roll);
                }
                break;
            }
        }

        const Matrix4 world = rotation.getRotationMatrix() * Matrix4::scaleMatrix(scale) * Matrix4::translateMatrix(render.pivot);
        return Matrix4::translateMatrix(instance.position) * inverseLinearModel * world;
    }

    // (SHADOW_LOD_TEXELS, cullsBatch, instanceVatData: RenderSystemShared.h)



    // getCenter() asserts on null/infinite boxes. New foliage (and any empty
    // instanced mesh) leaves worldAABB null; AABB::ZERO is the unloaded default
    // and is not a useful sample point.
    Vector3 meshProbeSamplePosition(const MeshComponent& mesh, const Transform& transform){
        if (mesh.worldAABB.isFinite() && mesh.worldAABB != AABB::ZERO){
            return mesh.worldAABB.getCenter();
        }
        return transform.worldPosition;
    }

    // An instanced billboard's rotation for the batch, in the entity's space: the camera's (the
    // view-aligned billboard), or with cylindrical only its turn about the mesh's up axis toward
    // the camera's view; a camera looking straight along that axis keeps lastYaw (radians)
    Quaternion instanceBillboardRotation(bool cylindrical, const Matrix4& cameraView, const Quaternion& entityWorldRotation, const Vector3& entityWorldScale, float& lastYaw){
        Quaternion cameraRotation;
        cameraRotation.fromRotationMatrix(cameraView.inverse());
        const Quaternion local = entityWorldRotation.inverse() * cameraRotation;
        if (!cylindrical)
            return local;
        // the camera's back (+Z of its frame: from the scene toward the camera) on the XZ plane
        const Vector3 back = local * Vector3(0.0f, 0.0f, 1.0f);
        // the entity's scale turns the face's normal by its inverse, so the yaw is taken with it
        // applied: the scaled face then faces the camera's side
        const float x = back.x * entityWorldScale.x;
        const float z = back.z * entityWorldScale.z;
        if (x * x + z * z > 1e-8f)
            lastYaw = std::atan2(x, z);
        return Quaternion(Angle::radToDefault(lastYaw), Vector3(0.0f, 1.0f, 0.0f));
    }

    // the u_vs_fade block (includes/instance_fade.glsl): the far range, the near range, the eye
    void applyInstanceFadeUniform(ObjectRender& render, int slot, const InstancedMeshComponent& instmesh, const Vector3& fadeEyeLocal){
        float fade[8] = {instmesh.fadeStart, instmesh.fadeEnd, instmesh.nearFadeStart, instmesh.nearFadeEnd,
            fadeEyeLocal.x, fadeEyeLocal.y, fadeEyeLocal.z, 0.0f};
        render.applyUniformBlock(slot, sizeof(fade), &fade);
    }

    // custom block of a forked shader, with the engine-written members refreshed: the shader
    // clock, the scene clock and the target's size
    void applyCustomUniforms(ObjectRender& render, CustomUniformBlock& block, float frameTime, float sceneTime, const Vector2& resolution){
        if (block.slot == -1)
            return;

        block.writeTime(frameTime);
        block.writeSceneTime(sceneTime);
        block.writeResolution(resolution.x, resolution.y);
        render.applyUniformBlock(block.slot, (unsigned int)block.data.size(), block.data.data());
    }

    // the custom blocks of a submesh's shaders: its material's parameters, else the mesh's
    // shader uniforms (forks set on the component), else the scene's values for its default
    // shader (when the submesh draws with it), else the manifest defaults
    void writeSubmeshCustomUniforms(const Scene* scene, const MeshComponent& mesh, Submesh& submesh){
        UniformChain chain;
        chain.values = &submesh.material.shaderParams;
        chain.fallback = &mesh.shaderUniforms;
        // a material with a shader of its own never inherits the scene's
        chain.sceneDefault = submesh.material.shader.empty() ? scene->getInheritedShaderUniforms(ShaderType::MESH, mesh.customShader.path) : nullptr;
        chain.manifest = submesh.manifest.get();
        // members bound to a global (Material::shaderGlobalBindings) take its current value
        chain.bindings = submesh.material.shaderGlobalBindings.empty() ? nullptr : &submesh.material.shaderGlobalBindings;
        submesh.customVSParams.writeValues(chain);
        submesh.customFSParams.writeValues(chain);
        submesh.customVSDepthParams.writeValues(chain);
        submesh.customFSDepthParams.writeValues(chain);
        // the extra pass: its own parameters, else its manifest's defaults (not while a component
        // copy still shares the original's: its load makes its own and writes that one)
        if (submesh.extraPass && submesh.extraPass.use_count() == 1){
            const ShaderUniformValues& passValues = submesh.material.extraPass->shaderParams;
            submesh.extraPass->customVSParams.writeValues(passValues, nullptr, submesh.extraPass->manifest.get());
            submesh.extraPass->customFSParams.writeValues(passValues, nullptr, submesh.extraPass->manifest.get());
        }
    }

    // the mesh blocks of both forks, from whichever pass draws first (depth runs before color)
    void writeCustomUniforms(const Scene* scene, MeshComponent& mesh){
        // a global a material binds changed since its blocks were written
        const uint64_t globalsVersion = ShaderGlobals::getVersion();
        if (mesh.globalsVersionSeen != globalsVersion){
            mesh.globalsVersionSeen = globalsVersion;
            for (int i = 0; i < mesh.numSubmeshes && !mesh.needUpdateShaderUniforms; i++){
                if (!mesh.submeshes[i].material.shaderGlobalBindings.empty())
                    mesh.needUpdateShaderUniforms = true;
            }
        }
        if (!mesh.needUpdateShaderUniforms)
            return;

        for (int i = 0; i < mesh.numSubmeshes; i++){
            writeSubmeshCustomUniforms(scene, mesh, mesh.submeshes[i]);
        }
        mesh.needUpdateShaderUniforms = false;
    }

    // both stages of a single-block component, from its values, the globals it binds and its
    // manifest defaults (globalsVersionSeen: the ShaderGlobals version they were written with)
    // sceneDefault: the scene's values for its default shader when the component draws with it
    void writeComponentUniforms(CustomUniformBlock& vsBlock, CustomUniformBlock& fsBlock, const ShaderUniformValues& values,
                                const ShaderManifest* manifest, const ShaderUniformValues* sceneDefault,
                                const ShaderGlobalBindings& bindings, uint64_t& globalsVersionSeen){
        UniformChain chain;
        chain.values = &values;
        chain.sceneDefault = sceneDefault;
        chain.manifest = manifest;
        chain.bindings = bindings.empty() ? nullptr : &bindings;
        vsBlock.writeValues(chain);
        fsBlock.writeValues(chain);
        globalsVersionSeen = ShaderGlobals::getVersion();
    }

    // both stages of a single-block component with manifest defaults, rewritten first when
    // its values changed (or a global it binds did)
    void applyComponentUniforms(ObjectRender& render, CustomUniformBlock& vsBlock, CustomUniformBlock& fsBlock,
                                const ShaderUniformValues& values, const ShaderManifest* manifest, const ShaderUniformValues* sceneDefault,
                                bool& needUpdate, const ShaderGlobalBindings& bindings, uint64_t& globalsVersionSeen,
                                float frameTime, float sceneTime, const Vector2& resolution){
        if (ShaderGlobals::isOutdated(bindings, globalsVersionSeen))
            needUpdate = true;
        if (needUpdate){
            writeComponentUniforms(vsBlock, fsBlock, values, manifest, sceneDefault, bindings, globalsVersionSeen);
            needUpdate = false;
        }
        applyCustomUniforms(render, vsBlock, frameTime, sceneTime, resolution);
        applyCustomUniforms(render, fsBlock, frameTime, sceneTime, resolution);
    }

    // how a shader without a manifest takes the post-processing colour under its resolved blend
    // (RenderSystem::PostColorBlend); a library shader's BLEND_* define does it in the shader
    uint8_t postColorBlendOf(const RenderState& state, bool libraryShader){
        if (libraryShader)
            return POST_BLEND_OWN;
        switch (state.blend){
            case BlendMode::ADDITIVE:      return POST_BLEND_ADDITIVE;
            case BlendMode::PREMULTIPLIED: return POST_BLEND_PREMULTIPLIED;
            case BlendMode::MULTIPLY:      return POST_BLEND_MULTIPLY;
            default:                       return POST_BLEND_OWN;
        }
    }

    MaterialBlendMode toMaterialBlendMode(BlendMode mode){
        switch (mode){
            case BlendMode::NONE:          return MaterialBlendMode::NONE;
            case BlendMode::PREMULTIPLIED: return MaterialBlendMode::PREMULTIPLIED;
            case BlendMode::ADDITIVE:      return MaterialBlendMode::ADDITIVE;
            case BlendMode::MULTIPLY:      return MaterialBlendMode::MULTIPLY;
            default:                       return MaterialBlendMode::ALPHA;
        }
    }

    BlendMode toBlendMode(MaterialBlendMode mode){
        switch (mode){
            case MaterialBlendMode::NONE:          return BlendMode::NONE;
            case MaterialBlendMode::PREMULTIPLIED: return BlendMode::PREMULTIPLIED;
            case MaterialBlendMode::ADDITIVE:      return BlendMode::ADDITIVE;
            case MaterialBlendMode::MULTIPLY:      return BlendMode::MULTIPLY;
            default:                               return BlendMode::ALPHA;
        }
    }

    DepthCompare toDepthCompare(MaterialDepthTest test){
        switch (test){
            case MaterialDepthTest::LESS:          return DepthCompare::LESS;
            case MaterialDepthTest::EQUAL:         return DepthCompare::EQUAL;
            case MaterialDepthTest::GREATER_EQUAL: return DepthCompare::GREATER_EQUAL;
            case MaterialDepthTest::GREATER:       return DepthCompare::GREATER;
            case MaterialDepthTest::NOT_EQUAL:     return DepthCompare::NOT_EQUAL;
            case MaterialDepthTest::ALWAYS:        return DepthCompare::ALWAYS;
            default:                               return DepthCompare::LESS_EQUAL;
        }
    }

    StencilCompare toStencilCompare(MaterialStencilCompare compare){
        switch (compare){
            case MaterialStencilCompare::NEVER:         return StencilCompare::NEVER;
            case MaterialStencilCompare::LESS:          return StencilCompare::LESS;
            case MaterialStencilCompare::EQUAL:         return StencilCompare::EQUAL;
            case MaterialStencilCompare::LESS_EQUAL:    return StencilCompare::LESS_EQUAL;
            case MaterialStencilCompare::GREATER:       return StencilCompare::GREATER;
            case MaterialStencilCompare::NOT_EQUAL:     return StencilCompare::NOT_EQUAL;
            case MaterialStencilCompare::GREATER_EQUAL: return StencilCompare::GREATER_EQUAL;
            default:                                    return StencilCompare::ALWAYS;
        }
    }

    StencilOp toStencilOp(MaterialStencilOp op){
        switch (op){
            case MaterialStencilOp::ZERO:       return StencilOp::ZERO;
            case MaterialStencilOp::REPLACE:    return StencilOp::REPLACE;
            case MaterialStencilOp::INCR_CLAMP: return StencilOp::INCR_CLAMP;
            case MaterialStencilOp::DECR_CLAMP: return StencilOp::DECR_CLAMP;
            case MaterialStencilOp::INVERT:     return StencilOp::INVERT;
            case MaterialStencilOp::INCR_WRAP:  return StencilOp::INCR_WRAP;
            case MaterialStencilOp::DECR_WRAP:  return StencilOp::DECR_WRAP;
            default:                            return StencilOp::KEEP;
        }
    }

    uint8_t clampStencilByte(int value){
        return (uint8_t)std::clamp(value, 0, 255);
    }

    // Stencil and colour write (phase 2): an explicit MaterialStencil (compare not AUTO) is
    // taken whole, else the manifest's stencil rule, else off; colorWrite -1 takes the
    // manifest's colorwrite, else every channel.
    void resolveStencilState(const MaterialStencil& stencil, int colorWrite, const ShaderManifestState& manifestState, RenderState& state){
        const MaterialStencil& resolved = (stencil.compare != MaterialStencilCompare::AUTO) ? stencil : manifestState.stencil;
        state.stencilEnabled = resolved.compare != MaterialStencilCompare::AUTO && resolved.compare != MaterialStencilCompare::DISABLED;
        if (state.stencilEnabled){
            state.stencilCompare = toStencilCompare(resolved.compare);
            state.stencilRef = clampStencilByte(resolved.ref);
            state.stencilReadMask = clampStencilByte(resolved.readMask);
            state.stencilWriteMask = clampStencilByte(resolved.writeMask);
            state.stencilPass = toStencilOp(resolved.pass);
            state.stencilFail = toStencilOp(resolved.fail);
            state.stencilDepthFail = toStencilOp(resolved.depthFail);
        }

        const int mask = (colorWrite >= 0) ? colorWrite : manifestState.colorWrite;
        state.colorWriteMask = (mask >= 0) ? (uint8_t)(mask & COLOR_WRITE_ALL) : (uint8_t)COLOR_WRITE_ALL;
    }

    // explicit value, else the manifest's @state value, else AUTO (the legacy behaviour)
    template<typename T>
    T resolveState(T explicitValue, T manifestValue){
        return (explicitValue != T::AUTO) ? explicitValue : manifestValue;
    }

    // Render state resolution (section 5.2) shared by meshes and components: the explicit
    // values, then the manifest's @state, then the legacy state given. Stencil and colour
    // write (phase 2) resolve the same way (resolveStencilState).
    RenderState resolveRenderState(MaterialBlendMode blendMode, MaterialCullMode cullMode, MaterialDepthWrite depthWrite,
                                   MaterialDepthTest depthTest, float offsetFactor, float offsetUnits,
                                   const MaterialStencil& stencil, int colorWrite,
                                   const ShaderManifestState* resolvedState, bool legacyBlended, bool legacyFaceCulling,
                                   CullingMode legacyCullingMode, WindingOrder windingOrder,
                                   bool& blended, bool& transparentQueue){
        const ShaderManifestState noState;
        const ShaderManifestState& manifestState = resolvedState ? *resolvedState : noState;

        RenderState state;
        state.windingOrder = windingOrder;

        // legacy: every pipeline blends with alpha, opaque objects included
        const MaterialBlendMode blend = resolveState(blendMode, manifestState.blend);
        if (blend == MaterialBlendMode::AUTO){
            blended = legacyBlended;
            state.blend = BlendMode::ALPHA;
        }else{
            blended = blend != MaterialBlendMode::NONE;
            state.blend = toBlendMode(blend);
        }

        const MaterialCullMode cull = resolveState(cullMode, manifestState.cull);
        if (cull == MaterialCullMode::AUTO){
            state.faceCulling = legacyFaceCulling;
            state.cullingMode = legacyCullingMode;
        }else{
            state.faceCulling = cull != MaterialCullMode::OFF;
            state.cullingMode = (cull == MaterialCullMode::FRONT) ? CullingMode::FRONT : CullingMode::BACK;
        }
        state.prepassFaceCulling = state.faceCulling;

        const MaterialDepthWrite write = resolveState(depthWrite, manifestState.depthWrite);
        state.depthWrite = (write == MaterialDepthWrite::AUTO) ? !blended : (write == MaterialDepthWrite::ENABLED);

        state.depthCompare = toDepthCompare(resolveState(depthTest, manifestState.depthTest));

        if (offsetFactor != 0.0f || offsetUnits != 0.0f){
            state.depthBiasSlope = offsetFactor;
            state.depthBias = offsetUnits;
        }else if (manifestState.hasDepthOffset){
            state.depthBiasSlope = manifestState.depthOffsetFactor;
            state.depthBias = manifestState.depthOffsetUnits;
        }

        if (manifestState.queue == ShaderQueue::TRANSPARENT){
            transparentQueue = true;
        }else if (manifestState.queue == ShaderQueue::GEOMETRY || manifestState.queue == ShaderQueue::ALPHATEST){
            transparentQueue = false;
        }else{
            transparentQueue = blended;
        }

        resolveStencilState(stencil, colorWrite, manifestState, state);

        return state;
    }

    // the manifest a shader string has, when it has one (built-in and forks without
    // manifest lines: null, the legacy path)
    std::shared_ptr<const ShaderManifest> findManifest(const std::string& shader){
        if (shader.empty())
            return nullptr;
        std::shared_ptr<const ShaderManifest> manifest = ShaderManifests::get(shader);
        return (manifest && manifest->present) ? manifest : nullptr;
    }

    bool usesAlphaBlend(const Material& material){
        return material.alphaMode == MaterialAlphaMode::BLEND ||
            (material.alphaMode == MaterialAlphaMode::AUTO &&
             (material.baseColorTexture.isTransparent() || material.baseColorFactor.w != 1.0f));
    }

    // the destination selects swapchain or RTT, a reflection pass reverses winding
    // and a canvas camera drops the depth buffer entirely
    PipelineType colorPipeline(const CameraComponent& camera, bool offscreenTarget){
        if (!offscreenTarget)
            return camera.depthTest ? PIP_DEFAULT : PIP_DEFAULT_NODEPTH;
        if (camera.invertCulling)
            return PIP_RTT_INVERT;
        return camera.depthTest ? PIP_RTT : PIP_RTT_NODEPTH;
    }

    // a canvas camera has no depth buffer to fix blending order, so it composites
    // strictly in submission order instead
    bool sortsByDistance(const CameraComponent& camera){
        return camera.depthTest && camera.transparentSort;
    }

    float readSpotMaskTexel(TextureData& source, int x, int y, bool useAlpha){
        x = std::clamp(x, 0, source.getWidth() - 1);
        y = std::clamp(y, 0, source.getHeight() - 1);

        const int channels = source.getChannels();
        const int bytesPerChannel = TextureData::getBytesPerChannel(source.getColorFormat());
        const size_t pixelOffset =
            (static_cast<size_t>(y) * static_cast<size_t>(source.getWidth()) + static_cast<size_t>(x)) *
            static_cast<size_t>(channels) * static_cast<size_t>(bytesPerChannel);
        const unsigned char* pixels = static_cast<const unsigned char*>(source.getData());

        if (source.getColorFormat() == ColorFormat::RED16){
            uint16_t value = 0;
            std::memcpy(&value, pixels + pixelOffset, sizeof(value));
            return static_cast<float>(value) / 65535.0f;
        }

        if (useAlpha && channels >= 4){
            return static_cast<float>(pixels[pixelOffset + 3]) / 255.0f;
        }

        if (channels >= 3){
            Vector3 color = Color::sRGBToLinear(
                static_cast<float>(pixels[pixelOffset]) / 255.0f,
                static_cast<float>(pixels[pixelOffset + 1]) / 255.0f,
                static_cast<float>(pixels[pixelOffset + 2]) / 255.0f);
            return 0.2126f * color.x + 0.7152f * color.y + 0.0722f * color.z;
        }

        return static_cast<float>(pixels[pixelOffset]) / 255.0f;
    }

    void rasterizeSpotMaskTile(TextureData& source, int tileIndex, int atlasWidth, std::vector<unsigned char>& atlas){
        const bool useAlpha = source.getColorFormat() == ColorFormat::RGBA && source.hasAlpha();
        const float sourceWidth = static_cast<float>(source.getWidth());
        const float sourceHeight = static_cast<float>(source.getHeight());

        for (int y = 0; y < SPOT_MASK_TILE_SIZE; y++){
            const float sourceY = ((static_cast<float>(y) + 0.5f) / static_cast<float>(SPOT_MASK_TILE_SIZE)) * sourceHeight - 0.5f;
            const int y0 = static_cast<int>(std::floor(sourceY));
            const int y1 = y0 + 1;
            const float fy = sourceY - static_cast<float>(y0);

            for (int x = 0; x < SPOT_MASK_TILE_SIZE; x++){
                const float sourceX = ((static_cast<float>(x) + 0.5f) / static_cast<float>(SPOT_MASK_TILE_SIZE)) * sourceWidth - 0.5f;
                const int x0 = static_cast<int>(std::floor(sourceX));
                const int x1 = x0 + 1;
                const float fx = sourceX - static_cast<float>(x0);

                const float top = readSpotMaskTexel(source, x0, y0, useAlpha) * (1.0f - fx) +
                                  readSpotMaskTexel(source, x1, y0, useAlpha) * fx;
                const float bottom = readSpotMaskTexel(source, x0, y1, useAlpha) * (1.0f - fx) +
                                     readSpotMaskTexel(source, x1, y1, useAlpha) * fx;
                const float value = top * (1.0f - fy) + bottom * fy;

                const int atlasX = tileIndex * SPOT_MASK_TILE_SIZE + x;
                atlas[static_cast<size_t>(y) * static_cast<size_t>(atlasWidth) + static_cast<size_t>(atlasX)] =
                    static_cast<unsigned char>(std::round(std::clamp(value, 0.0f, 1.0f) * 255.0f));
            }
        }
    }
}

